export const CORE_SECTION_IDS = SECTIONS.filter((s) => s.core).map((s) => s.id);
export const OPTIONAL_SECTION_IDS = SECTIONS.filter((s) => s.optional).map((s) => s.id);
export const SECTION_BY_ID = Object.fromEntries(SECTIONS.map((s) => [s.id, s]));

/* ------------------------------------------------------------------ */
/* Planner + source grounding                                          */
/* ------------------------------------------------------------------ */

export const PLANNER_PROMPT = (topic, sourceText) => `Analyse this study request and return a plan.

Topic: "${topic}"
${sourceText ? `\nSource material (first 6000 chars):\n"""\n${sourceText.slice(0, 6000)}\n"""\n` : ''}
Return ONLY JSON:
{
  "title": "a clean, specific notes title",
  "subject": "the academic subject",
  "level": "school|undergraduate|postgraduate",
  "unit": "the likely unit/chapter name, or empty string",
  "emoji": "one topic-appropriate emoji",
  "subtopics": ["6-14 examinable sub-topics in teaching order"],
  "has_math": true,
  "has_derivations": true,
  "has_numericals": true,
  "estimated_minutes": 90,
  "research_queries": ["4-6 web search queries that would sharpen these notes"]
}
Never invent a syllabus code. If the topic is ambiguous, choose the most common academic reading of it.`;

export function scopeBlock(plan, sourceText, research) {
  const parts = [];
  if (plan?.subject) parts.push(`\nSubject: ${plan.subject} (${plan.level || 'undergraduate'})`);
  if (plan?.unit) parts.push(`Unit: ${plan.unit}`);
  if (plan?.subtopics?.length) parts.push(`Sub-topics to cover: ${plan.subtopics.join('; ')}`);
  if (sourceText) {
    parts.push(
      `\nGROUND YOUR NOTES IN THIS SOURCE MATERIAL. Prefer its notation, symbols and worded conventions. Do not contradict it:\n"""\n${sourceText.slice(0, 9000)}\n"""`
    );
  }
  if (research) {
    parts.push(`\nVERIFIED RESEARCH CONTEXT (use for accuracy, cite inline as [n]):\n${research.slice(0, 6000)}`);
  }
  return parts.length ? `\n${parts.join('\n')}` : '';
}

/* Chat tutor that answers strictly against the generated notes. */
export const TUTOR_SYSTEM = `You are the StudyForge study tutor for one specific lesson.
Answer using the lesson notes provided as context. Use LaTeX for math.
If the answer is not in the notes, say so plainly and then answer from general knowledge, clearly marked as "beyond these notes".
Be concise: lead with the answer, then the reasoning, then a worked micro-example when the question is quantitative.`;
